(function(){
 let session=null;try{session=JSON.parse(sessionStorage.getItem('g9star-admin-session')||'null');if(session){const payload=JSON.parse(atob(session.accessToken.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.exp*1000<Date.now())session=null}}catch{session=null}
 window.G9STAR.adminSession=session;
 const panel=document.querySelector('#adminLoginPanel'),layout=document.querySelector('.admin-layout');panel.hidden=!!session;layout.hidden=!session;
 document.querySelector('.role-switch').hidden=true;document.querySelector('#activeUser').textContent=session?.user||'로그인 필요';
 if(session){document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===session.role));const logout=document.createElement('button');logout.textContent='로그아웃';logout.className='admin-button';logout.onclick=()=>{sessionStorage.removeItem('g9star-admin-session');location.reload()};document.querySelector('.admin-header').append(logout)}
 document.querySelector('#adminLoginForm').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button'),message=document.querySelector('#adminLoginMessage');button.disabled=true;try{const turnstileToken=await window.G9STAR.challengeToken();const response=await fetch(window.G9STAR.apiBase+'/v1/admin/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({login:document.querySelector('#adminLogin').value,password:document.querySelector('#adminPassword').value,turnstileToken})});const body=await response.json();if(!response.ok)throw Error(body.error?.message||'로그인하지 못했습니다.');sessionStorage.setItem('g9star-admin-session',JSON.stringify(body));location.reload()}catch(error){message.textContent=error.message;button.disabled=false}};
})();
